/* Compare upstream scoring options on independent labelled synthetic WAVs.
 * Uses fixed wLipSync WASM, never supplies labels to the classifier.
 * Fixture WAV/sequence are generated by serve_lipsync_acceptance.py.
 */
const fs = require('node:fs'), path = require('node:path')
const root = path.resolve(__dirname, '..')
;(async () => {
  const profile = JSON.parse(fs.readFileSync(process.env.LIPSYNC_PROFILE || path.join(root, 'web/src/avatar/lipsync/local-vits-profile.json')))
  const sequence = JSON.parse(fs.readFileSync(path.join(root, 'artifacts/vowel-acceptance/sequence.json')))
  const wav = fs.readFileSync(path.join(root, 'artifacts/vowel-acceptance/equal-rms-vowels.wav'))
  // This fixture generator writes canonical PCM16 mono 16k WAV headers.
  if (wav.readUInt16LE(22) !== 1 || wav.readUInt32LE(24) !== 16000 || wav.toString('ascii',36,40) !== 'data') throw Error('Unexpected fixture WAV')
  const samples = Float32Array.from({ length: (wav.length - 44) / 2 }, (_, i) => wav.readInt16LE(44 + i * 2) / 32768)
  const results = []
  for (const standardization of [false, true]) for (const method of [0, 1, 2]) {
    const memory = new WebAssembly.Memory({ initial: 4 })
    const { instance } = await WebAssembly.instantiate(fs.readFileSync(process.env.WLIPSYNC_WASM || path.join(root, 'web/vendor/wlipsync/wlipsync.wasm')), { env: { memory } })
    const api = instance.exports, pointer = api.load_profile(16000,1024,30,method,6,48,standardization?1:0)
    new Float32Array(memory.buffer, pointer, 6*48*12).set(profile.mfccs.flatMap(x => x.mfccCalibrationDataList.flatMap(f => f.array)))
    api.precompute_profile(); api.set_input(16000)
    const input = new Float32Array(memory.buffer, api.get_input_buffer(), api.get_input_buffer_size())
    let cursor = 0
    const counts = Object.fromEntries(sequence.map(x => [x.label, {}]))
    for (let i = 0; i < samples.length; i += 128) {
      for (const sample of samples.subarray(i,i+128)) { input[cursor] = sample; cursor = (cursor+1)%input.length }
      if ((i+128)%512 !== 0) continue
      const index = api.execute(cursor), predicted = profile.mfccs[index].name, t=(i+128)/16000
      const segment = sequence.find(x => t>x.start+.35 && t<x.end-.1)
      if (segment) counts[segment.label][predicted] = (counts[segment.label][predicted]||0)+1
    }
    const total = Object.values(counts).flatMap(Object.values).reduce((a,b)=>a+b,0)
    const correct = Object.entries(counts).reduce((a,[label,c])=>a+(c[label]||0),0)
    results.push({ method, standardization, counts, correct, total, fraction:correct/total })
  }
  const result = { method:'Upstream scoring configuration comparison on one independent synthetic sequence, not general phoneme accuracy. Browser resampling/render QA required after any selection.', results }
  fs.writeFileSync(path.join(root,'artifacts/lip-calibration/scoring-options.json'),JSON.stringify(result,null,2))
  console.log(JSON.stringify(result,null,2))
})().catch(e=>{console.error(e);process.exitCode=1})
